[CmdletBinding()]
param([Parameter(Mandatory = $true)][string]$FbeExe, [ValidateRange(30,300)][int]$TimeoutSeconds = 180)
$ErrorActionPreference='Stop'; $root=Join-Path ([IO.Path]::GetTempPath()) ('fbe-normal-recovery-'+[guid]::NewGuid().ToString('N')); New-Item -ItemType Directory -Path $root -Force|Out-Null
try {
 $file=Join-Path $root 'book.fb2'; $a=Join-Path $root 'create.txt'; $b=Join-Path $root 'verify.txt'; [IO.File]::WriteAllText($file,'<?xml version="1.0"?><FictionBook xmlns="http://www.gribuser.ru/xml/fictionbook/2.0"><description><title-info><genre>prose</genre><author><first-name>Runtime</first-name><last-name>Test</last-name></author><book-title>Runtime</book-title><lang>en</lang></title-info><document-info><author><nickname>FBE</nickname></author><program-used>FBE</program-used><date value="2026-01-01">1</date><id>1</id><version>1.0</version></document-info></description><body><section><p>x</p></section></body></FictionBook>',[Text.UTF8Encoding]::new($false))
 $om,$os=$env:FBE_NEXT_TEST_MODE,$env:FBE_NEXT_TEST_SCENARIO; try {$env:FBE_NEXT_TEST_MODE='1';$env:FBE_NEXT_TEST_SCENARIO='normal-recovery-create';$p=Start-Process $FbeExe -ArgumentList ('--portable -b "{0}" "{1}"' -f $a,$file) -WorkingDirectory (Split-Path $FbeExe) -PassThru;if(-not $p.WaitForExit($TimeoutSeconds*1000)){Stop-Process $p -Force;throw 'create timeout'};$env:FBE_NEXT_TEST_SCENARIO='normal-recovery-verify';$p=Start-Process $FbeExe -ArgumentList ('--portable -b "{0}"' -f $b) -WorkingDirectory (Split-Path $FbeExe) -PassThru;if(-not $p.WaitForExit($TimeoutSeconds*1000)){Stop-Process $p -Force;throw 'verify timeout'};$s=Get-Content $b -Raw;foreach($x in 'identity=1','dirty=1','cleaned=1'){if($p.ExitCode -ne 0 -or $s -notmatch [regex]::Escape($x)){throw "normal recovery regression: $s"}}}finally{$env:FBE_NEXT_TEST_MODE,$env:FBE_NEXT_TEST_SCENARIO=$om,$os}
}finally{Remove-Item $root -Recurse -Force -ErrorAction SilentlyContinue}
Write-Host 'Normal recovery runtime regression passed.'
